CREATE TABLE sis.student_enrollment (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    student_id uuid NOT NULL,
    academic_year_id uuid NOT NULL,
    class_section_id uuid,
    roll_number varchar(20),
    id_card_number varchar(40),
    board_registration_number varchar(40),
    enrollment_status varchar(30) NOT NULL DEFAULT  'enrolled',
    result_status varchar(30) NOT NULL DEFAULT  'pending',
    enrolled_on date,
    left_on date,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    effective_from date,
    effective_to date,
    previous_enrollment_id uuid,
    change_reason varchar(30) NOT NULL DEFAULT 'initial',
    CONSTRAINT pk_student_enrollment PRIMARY KEY (id),
    CONSTRAINT ck_student_enrollment_enrollment_status CHECK (enrollment_status IN ('enrolled', 'promoted', 'detained', 'left', 'completed')),
    CONSTRAINT ck_student_enrollment_result_status CHECK (result_status IN ('pending', 'pass', 'fail')),
    CONSTRAINT ck_student_enrollment_change_reason CHECK (change_reason IN ('initial', 'promotion', 'transfer_in', 'section_change', 're_admission', 'correction')),
    CONSTRAINT ck_student_enrollment_effective CHECK (effective_to IS NULL OR effective_from IS NULL OR effective_to >= effective_from),
    CONSTRAINT uq_student_enrollment_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE sis.student_enrollment IS 'Student''s placement in a class section for an academic year (K-12 placement).';
