-- === P0-05 / P0-06 / P1-01 / A3: enrollment history, HE registration binding, student leave ===

CREATE TABLE sis.student_leave_request (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    tenant_id uuid NOT NULL,
    student_id uuid NOT NULL,
    academic_year_id uuid,
    from_date date NOT NULL,
    to_date date NOT NULL,
    day_part varchar(20) NOT NULL DEFAULT 'full_day',
    reason varchar(500),
    status varchar(20) NOT NULL DEFAULT 'pending',
    requested_by_user_id uuid,
    decided_by_user_id uuid,
    decided_at timestamptz,
    decision_note varchar(300),
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_student_leave_request PRIMARY KEY (id),
    CONSTRAINT ck_student_leave_request_status CHECK (status IN ('pending', 'approved', 'rejected', 'cancelled')),
    CONSTRAINT ck_student_leave_request_day_part CHECK (day_part IN ('full_day', 'first_half', 'second_half')),
    CONSTRAINT ck_student_leave_request_dates CHECK (to_date >= from_date),
    CONSTRAINT uq_student_leave_request_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE sis.student_leave_request IS 'Leave requested for a student (by a guardian or staff), approved by staff; approved leave explains absences in attendance.';
COMMENT ON COLUMN sis.student_leave_request.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN sis.student_leave_request.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN sis.student_leave_request.student_id IS 'Student the leave is for.';
COMMENT ON COLUMN sis.student_leave_request.academic_year_id IS 'Academic year the leave falls in.';
COMMENT ON COLUMN sis.student_leave_request.from_date IS 'First day of leave.';
COMMENT ON COLUMN sis.student_leave_request.to_date IS 'Last day of leave.';
COMMENT ON COLUMN sis.student_leave_request.day_part IS 'full_day / first_half / second_half.';
COMMENT ON COLUMN sis.student_leave_request.reason IS 'Stated reason.';
COMMENT ON COLUMN sis.student_leave_request.status IS 'pending / approved / rejected / cancelled.';
COMMENT ON COLUMN sis.student_leave_request.requested_by_user_id IS 'User who filed the request (guardian or staff).';
COMMENT ON COLUMN sis.student_leave_request.decided_by_user_id IS 'Staff user who decided it.';
COMMENT ON COLUMN sis.student_leave_request.decided_at IS 'When it was decided.';
COMMENT ON COLUMN sis.student_leave_request.decision_note IS 'Note recorded with the decision.';
COMMENT ON COLUMN sis.student_leave_request.created_at IS 'Row creation time.';
COMMENT ON COLUMN sis.student_leave_request.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN sis.student_leave_request.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN sis.student_leave_request.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN sis.student_leave_request.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN sis.student_leave_request.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
ALTER TABLE sis.student_leave_request ADD CONSTRAINT fk_student_leave_request_student_id FOREIGN KEY (student_id, tenant_id) REFERENCES sis.student (id, tenant_id) ON DELETE CASCADE;
CREATE INDEX ix_student_leave_request_student_id ON sis.student_leave_request (student_id);
ALTER TABLE sis.subject_registration ADD CONSTRAINT fk_subject_registration_program_enrollment_id FOREIGN KEY (program_enrollment_id, tenant_id) REFERENCES sis.program_enrollment (id, tenant_id) ON DELETE RESTRICT;
CREATE INDEX ix_subject_registration_program_enrollment_id ON sis.subject_registration (program_enrollment_id);
ALTER TABLE sis.student_enrollment ADD CONSTRAINT fk_student_enrollment_previous_enrollment_id FOREIGN KEY (previous_enrollment_id, tenant_id) REFERENCES sis.student_enrollment (id, tenant_id) ON DELETE SET NULL (previous_enrollment_id);
CREATE INDEX ix_student_enrollment_previous_enrollment_id ON sis.student_enrollment (previous_enrollment_id);
CREATE UNIQUE INDEX uq_student_enrollment_open ON sis.student_enrollment (tenant_id, student_id, academic_year_id) WHERE deleted_at IS NULL AND effective_to IS NULL;
CREATE UNIQUE INDEX uq_promotion_once ON sis.promotion (tenant_id, student_id, from_academic_year_id) WHERE status <> 'rejected' AND deleted_at IS NULL;
CREATE UNIQUE INDEX uq_subject_registration_slot ON sis.subject_registration (tenant_id, program_enrollment_id, academic_year_id, academic_term_id) NULLS NOT DISTINCT WHERE deleted_at IS NULL;

-- === P1-16: uniform reference-data shape ===

CREATE UNIQUE INDEX uq_student_category_scope_code ON sis.student_category (institution_id, code) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX uq_relationship_type_scope_code ON sis.relationship_type (tenant_id, code) WHERE deleted_at IS NULL;
CREATE UNIQUE INDEX uq_activity_type_scope_code ON sis.activity_type (tenant_id, code) WHERE deleted_at IS NULL;

-- === P1-13: transactional outbox / inbox ===

CREATE TABLE sis.outbox_event (
    id bigint GENERATED ALWAYS AS IDENTITY,
    tenant_id uuid NOT NULL,
    event_type varchar(120) NOT NULL,
    aggregate_type varchar(80) NOT NULL,
    aggregate_id uuid NOT NULL,
    payload text NOT NULL,
    occurred_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    CONSTRAINT pk_sis_outbox_event PRIMARY KEY (id)
);
COMMENT ON TABLE sis.outbox_event IS 'Transactional outbox of the sis module: events written in the same transaction as the change, published to the bus by a relay, then pruned. Ordered by the identity column.';
COMMENT ON COLUMN sis.outbox_event.id IS 'Monotonic sequence; publish order.';
COMMENT ON COLUMN sis.outbox_event.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN sis.outbox_event.event_type IS 'Event name (module.entity.verb).';
COMMENT ON COLUMN sis.outbox_event.aggregate_type IS 'Entity kind the event is about.';
COMMENT ON COLUMN sis.outbox_event.aggregate_id IS 'Entity id the event is about.';
COMMENT ON COLUMN sis.outbox_event.payload IS 'Serialised event (opaque message envelope).';
COMMENT ON COLUMN sis.outbox_event.occurred_at IS 'When the change committed.';
COMMENT ON COLUMN sis.outbox_event.published_at IS 'When the relay published it (NULL = pending).';
CREATE INDEX ix_sis_outbox_event_pending ON sis.outbox_event (id) WHERE published_at IS NULL;
CREATE TABLE sis.inbox_event (
    event_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    event_type varchar(120) NOT NULL,
    received_at timestamptz NOT NULL DEFAULT now(),
    processed_at timestamptz,
    processing_error text,
    CONSTRAINT pk_sis_inbox_event PRIMARY KEY (event_id)
);
COMMENT ON TABLE sis.inbox_event IS 'Inbox of the sis module: ids of consumed events, kept so redeliveries are processed exactly once.';
COMMENT ON COLUMN sis.inbox_event.event_id IS 'Global id of the consumed event.';
COMMENT ON COLUMN sis.inbox_event.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN sis.inbox_event.event_type IS 'Event name.';
COMMENT ON COLUMN sis.inbox_event.received_at IS 'First delivery time.';
COMMENT ON COLUMN sis.inbox_event.processed_at IS 'When handling committed (NULL = in flight).';
COMMENT ON COLUMN sis.inbox_event.processing_error IS 'Last handling error, if any.';

