    CONSTRAINT uq_sis_number_sequence_1 UNIQUE NULLS NOT DISTINCT (tenant_id, institution_id, sequence_code, period_key)
);
COMMENT ON TABLE sis.number_sequence IS 'Module-local gap-aware number source of the sis module (admission (enrolment), identity-card, bonafide-certificate and subject-registration reference numbers). Read with SELECT ... FOR UPDATE inside the issuing transaction; never shared with another module.';
