COMMENT ON COLUMN sis.number_sequence.institution_id IS 'Institution scope (NULL = tenant-wide sequence).';
COMMENT ON COLUMN sis.number_sequence.sequence_code IS 'Which number series of this module (admission (enrolment), identity-card, bonafide-certificate and subject-registration reference numbers).';
COMMENT ON COLUMN sis.number_sequence.period_key IS 'Reset period (fiscal year key such as FY2026; empty = never resets).';
COMMENT ON COLUMN sis.number_sequence.prefix IS 'Rendered number prefix.';
COMMENT ON COLUMN sis.number_sequence.padding IS 'Zero padding width of the numeric part.';
COMMENT ON COLUMN sis.number_sequence.next_value IS 'Next number to issue.';
COMMENT ON COLUMN sis.number_sequence.created_at IS 'Row creation time.';
COMMENT ON COLUMN sis.number_sequence.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN sis.number_sequence.updated_at IS 'Last modification time (set by the application on every update).';
COMMENT ON COLUMN sis.number_sequence.updated_by IS 'User account that last modified the row (audit reference; not FK-constrained).';
COMMENT ON COLUMN sis.number_sequence.deleted_at IS 'Soft-delete timestamp (NULL = live row).';
COMMENT ON COLUMN sis.number_sequence.row_version IS 'Optimistic-lock version, incremented on every update; used as the ETag.';
ALTER TABLE sis.number_sequence ENABLE ROW LEVEL SECURITY;
ALTER TABLE sis.number_sequence FORCE ROW LEVEL SECURITY;
